"""Text-to-SQL harness: draft -> execute & inspect -> one targeted repair.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}      (hint is BIRD's evidence; "" for Spider)
  env.chat(messages, max_tokens=None) -> str     policy call (capped per task: env.max_calls)
  env.schema(db_id) -> str                       CREATE statements of the database
  env.execute(sql, max_rows=20) -> dict          read-only run: {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str                 column descriptions if the dataset ships them, else ""
  env.prompt(name) -> str                        text of a file in this harness (e.g. "system_prompt.md")
  env.config -> dict                             parsed config.json
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
LITERAL = re.compile(r"'((?:[^']|'')*)'")
CREATE_HEAD = re.compile(
    r'CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?["`\[]?([A-Za-z_][A-Za-z0-9_]*)["`\]]?\s*\(',
    re.I,
)
COL_LINE = re.compile(r'^\s*["`\[]?([A-Za-z_][A-Za-z0-9_]*)["`\]]?\s+([A-Za-z]+)')
SQL_WORDS = {
    "PRIMARY", "FOREIGN", "UNIQUE", "CHECK", "CONSTRAINT", "KEY", "INDEX",
    "TABLE", "CREATE", "SELECT", "GROUP", "ORDER", "HAVING", "WHERE",
}


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _tables(schema_text):
    """[(table_name, [(col_name, declared_type), ...]), ...] from CREATE statements."""
    out = []
    heads = list(CREATE_HEAD.finditer(schema_text or ""))
    for i, m in enumerate(heads):
        end = heads[i + 1].start() if i + 1 < len(heads) else len(schema_text)
        body = schema_text[m.end():end]
        depth, cut = 1, len(body)
        for j, ch in enumerate(body):
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    cut = j
                    break
        cols = []
        for line in body[:cut].split(","):
            cm = COL_LINE.match(line)
            if not cm:
                continue
            name, typ = cm.group(1), cm.group(2).upper()
            if name.upper() in SQL_WORDS:
                continue
            cols.append((name, typ))
        out.append((m.group(1), cols))
    return out


def _fmt_res(res, limit=6):
    if not res.get("ok"):
        return "ERROR: %s" % str(res.get("error"))[:300]
    rows = res.get("rows") or []
    head = "columns: %s | n_rows: %s" % (res.get("columns"), res.get("n_rows"))
    if not rows:
        return head + " | (no rows)"
    shown = "; ".join(str(r)[:160] for r in rows[:limit])
    return head + "\nfirst rows: " + shown[:900]


def _probe_literals(sql, tables, env, budget=4):
    """For string literals used in the draft, show what the DB actually stores."""
    lits = []
    for raw in LITERAL.findall(sql):
        v = raw.replace("''", "'").strip()
        if len(v) >= 3 and v not in lits:
            lits.append(v)
    notes = []
    for v in lits[:3]:
        if budget <= 0:
            break
        esc = v.replace("'", "''")
        hits = []
        for tname, cols in tables:
            for cname, typ in cols:
                if not any(k in typ for k in ("CHAR", "TEXT", "CLOB")):
                    continue
                probe = (
                    'SELECT "%s", COUNT(*) FROM "%s" WHERE "%s" = \'%s\' '
                    'OR "%s" LIKE \'%%%s%%\' GROUP BY 1 ORDER BY 2 DESC LIMIT 4'
                    % (cname, tname, cname, esc, cname, esc)
                )
                r = env.execute(probe, max_rows=4)
                budget -= 1
                if r.get("ok") and r.get("rows"):
                    hits.append("%s.%s -> %s" % (tname, cname, str(r["rows"])[:200]))
                if budget <= 0 or len(hits) >= 3:
                    break
            if budget <= 0 or len(hits) >= 3:
                break
        if hits:
            notes.append("Literal '%s': actual matching stored values: %s" % (v, " | ".join(hits)))
        else:
            notes.append(
                "Literal '%s': no exact or substring match found in the sampled text columns; "
                "the stored spelling/casing may differ." % v
            )
    return notes


def _suspect_reasons(question, sql, res):
    reasons = []
    if not res.get("ok"):
        reasons.append("The query failed to execute.")
        return reasons
    if not (res.get("rows") or []):
        reasons.append(
            "The query returned ZERO rows. Likely causes: a string literal whose casing/spelling/"
            "trailing spaces differ from the stored values, filtering on the wrong column, an "
            "over-restrictive WHERE, a wrong join key, or assuming a directed link where the data "
            "stores it in the other direction."
        )
    q = (question or "").lower()
    ncols = len(res.get("columns") or [])
    broad = any(k in q for k in ("detail", "all information", "all the information", "everything", "all fields"))
    if broad and ncols <= 2 and "*" not in sql:
        reasons.append(
            "The question asks for details / all information about records, but the query selects "
            "only %d column(s); such questions usually expect every column of the target table "
            "(SELECT T.*)." % ncols
        )
    return reasons


def solve(task, env):
    cfg = env.config or {}
    max_tokens = cfg.get("max_tokens", 800)
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s\n\nQuestion: %s" % (task["db_id"], schema, task["question"])
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\n\nColumn descriptions:\n" + desc.strip()[:2000]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=max_tokens)
    sql = extract_sql(reply)

    calls_left = getattr(env, "max_calls", 2) - 1
    if calls_left <= 0 or not sql:
        return {"sql": sql}

    res = env.execute(sql, max_rows=8)
    reasons = _suspect_reasons(task["question"], sql, res)
    if not reasons:
        return {"sql": sql}

    feedback = ["Your draft query:", sql, "", "Execution check:", _fmt_res(res), ""]
    feedback += reasons
    if not res.get("ok") or not (res.get("rows") or []):
        try:
            feedback += _probe_literals(sql, _tables(schema), env)
        except Exception:
            pass
    feedback.append(
        "\nRevise the query so it correctly answers the question. Use the ACTUAL stored values "
        "shown above for string filters (match their exact casing and spacing, or use a robust "
        "LIKE pattern). Reconsider which column the filter belongs to, whether joins and relation "
        "directions are right, and whether the question wants all columns of a table. Keep the "
        "projection minimal unless the question asks for details/all information. "
        "Return ONLY the corrected query in a single ```sql code block."
    )
    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": "\n".join(feedback)})
    reply2 = env.chat(messages, max_tokens=max_tokens)
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = env.execute(sql2, max_rows=8)
    # Prefer the revision when it runs; if both run, prefer the one that returns data.
    if res2.get("ok") and (not res.get("ok") or (res2.get("rows") or not res.get("rows"))):
        return {"sql": sql2}
    if res.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}

